#include <bits/stdc++.h>
using namespace std;

struct Val {
    long double fi, se;
    Val(long double a = 0.0, long double b = 0.0) : fi(a), se(b) {}
};

Val Add(const Val& f, const Val& s) {
    return Val(f.fi + s.fi, f.se + s.se);
}

Val Sub(const Val& f, const Val& s) {
    return Val(f.fi - s.fi, f.se - s.se);
}

Val Mult(const Val& f, long double w) {
    return Val(f.fi * w, f.se * w);
}

Val Div(const Val& f, long double w) {
    return Val(f.fi / w, f.se / w);
}

int main() {
    int n, k;
    cin >> n >> k;
    vector<double> p(n);
    for (int i = 0; i < n; ++i) cin >> p[i];

    vector<Val> dp(1 << n);
    for (int i = 0; i < n; ++i) {
        vector<double> p_copy = p;
        vector<Val> res(1 << n);
        for (int mask = 0; mask < (1 << n); ++mask) {
            res[mask] = Val(0.0, 0.0);
        }
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (mask & (1 << i)) continue;
            Val sum(0.0, 0.0);
            double same = 0.0;
            for (int j = 0; j < n; ++j) {
                if (j != i && (mask & (1 << j))) {
                    same += p[j];
                    sum = Add(sum, Mult(res[mask ^ (1 << j)], p[j]));
                }
            }
            res[mask] = Div(sum, 1.0 - same);
        }
        Val total(1.0, 0.0);
        for (int mask = 1; mask < (1 << n); ++mask) {
            if (!(mask & (1 << i))) {
                total = Add(total, res[mask]);
            }
        }
        double alp = (1.0 - total.se) / total.fi;
        Val bad(0.0, 0.0);
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (mask & (1 << i)) continue;
            if (__builtin_popcount(mask) >= k) {
                bad = Add(bad, res[mask]);
            }
        }
        cout << fixed << setprecision(12) << 1.0 - (alp * bad.fi + bad.se) << (i + 1 == n ? '\n' : ' ');
    }
    return 0;
}
